import { useQuery } from '@tanstack/react-query'

export type AdvertItem = {
  id: string
  Id_CmsInscription: string
  owner_id: string
  Sujet: string
  title: string
  description: string
  Text: string
  classe: string
  classe_slug: string
  category: string
  Price: number | null
  image: string
  Video: string
  LinkToshop: string
  ShowCallAdvertiserLink: number
  ShowOrderLink: number
  ShowSendMessageLink: number
  ShowLink: number
  LinkLabel: string | null
  Annonceur: string
  NbVisite: number
  characteristics: any[]
}

export type AdPreview = {
  id: string
  title: string
  image: string
  link: string

  Video?: string
}

const API_BASE = 'https://betaapiw.fibladi.com/api/ads/feed'

export const fetchAdsFeed = async (limit: number): Promise<AdPreview[]> => {
  const res = await fetch(`${API_BASE}${limit > 1 ? '?limit=' + limit : ''}`)
  if (!res.ok) {
    throw new Error('Failed to fetch ads feed')
  }
  const json: AdvertItem[] = await res.json()

  return json.map((ad) => ({
    id: ad.id,
    title: ad.title,
    image: ad.image,
    link: ad.LinkToshop,

    Video: getEmbedUrl(ad.Video)!,
  }))
}

export const useAdsFeed = (limit: number) => {
  return useQuery<AdPreview[], Error>({
    queryKey: ['adsFeed', limit],
    queryFn: () => fetchAdsFeed(limit),
    staleTime: 1000 * 60 * 20, // 2 minutes
  })
}

function getEmbedUrl(url: string) {
  if (!url) return null

  // YouTube
  if (url.includes('youtube.com') || url.includes('youtu.be')) {
    let id = null

    // YouTube Shorts: https://www.youtube.com/shorts/VIDEO_ID
    if (url.includes('/shorts/')) {
      id = url.split('/shorts/')[1]?.split('?')[0]
    }
    // Short URL: https://youtu.be/VIDEO_ID
    else if (url.includes('youtu.be')) {
      id = url.split('/').pop()?.split('?')[0]
    }
    // Standard URL: https://www.youtube.com/watch?v=VIDEO_ID
    else {
      id = new URL(url).searchParams.get('v')
    }

    return id ? `https://www.youtube.com/embed/${id}` : null
  }

  // Instagram
  if (url.includes('instagram.com')) {
    return url
  }

  // // Facebook
  // if (url.includes('facebook.com')) {
  //   if (url.includes('/share/') || url.includes('/profile')) {
  //     return null
  //   }
  //   return `https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(
  //     url,
  //   )}&show_text=false`
  // }

  return null
}
